<script lang="ts">
import {onMount,untrack} from 'svelte';import {createFixtureBridge} from '@unofficial-krds/test-contracts/driver';import CatalogExamples from './CatalogExamples.svelte';import {catalogSeed,serializable} from './catalog-state.js';
let {componentId,caseId}:{componentId:string;caseId:string}=$props();const initial=untrack(()=>catalogSeed(componentId,caseId));let snapshot=$state<Record<string,any>>(initial);let ready=$state(false);let bridge:ReturnType<typeof createFixtureBridge>;const handles=new Map<string,File>();
onMount(()=>{for(const record of initial.files??[]){const material=(initial.__host?.fileFixtures??[]).find((x:any)=>x.id===(record.fileFixtureId??record.id)||x.name===record.file?.name)??record.file??record;handles.set(record.id,new File([material.contents??material.text??'local file'],material.name??'example.txt',{type:material.type??'text/plain',lastModified:0}));}bridge=createFixtureBridge('svelte',initial);const original=bridge.setState.bind(bridge);bridge.setState=async(patch)=>{const host=patch.__host as Record<string,unknown>|undefined;await original({...patch,...(host?.routeChange?{__routeRemoved:true}:{})});};const off=bridge.subscribe(next=>snapshot=next);ready=true;return()=>{off();bridge.dispose();handles.clear();};});
function patch(next:Record<string,any>){for(const record of next.files??[])if(record.file instanceof File)handles.set(record.id,record.file);void bridge.setState(serializable(next));}
function emit(name:string,detail:any,next?:Record<string,any>){bridge.recordEvent(name,serializable(detail));if(next){next={...next};for(const key of ['value','checked','open','index','playing','expandedId','expandedIds','expanded','mobileOpen','openIds','selectedTopicId','activePanel','stepId'])if(next[key]!==undefined&&initial[key]===undefined)delete next[key];}if(next&&snapshot.__host.acceptChanges!==false&&!snapshot.rejectChanges&&!(name==='openChange'&&detail.open===false&&snapshot.__host.acceptClose===false))patch(next);}
const native=$derived(componentId==='file-upload'?{...snapshot,files:(snapshot.files??[]).map((record:any)=>({...record,file:handles.get(record.id)})).filter((record:any)=>record.file)}:snapshot);
</script>{#if ready}<div role="status" aria-label="Fixture health">ready</div><CatalogExamples {componentId} state={native} {patch} {emit}/>{/if}